        clearTimeout(this._idleTimer);
        this._idleTimer = setTimeout(() => { this._moving = false; }, 900);
        // Si estaba de capricho por el mapa, vuelve corriendo a tu punto y saluda.
        if (this._explorando) this._volverATuPunto();
